def _dict_to_xml(data):
    """
    Helper function to convert a data dictionary into xml.

    data
        The data dictionary to convert.
    """
    if not data:
        return ""
    if not isinstance(data, dict):
        data = xmltodict.parse(data)
    return xmltodict.unparse(data)


def _get_xml_value(xml, key):
    """
    Helper function to get the value of a key in an xml data dictionary.

    xml
        The xml data dictionary to get the value from.

    key
        The key to get the value for.
    """
    if not xml:
        return None
    if not isinstance(xml, dict):
        xml = xmltodict.parse(xml)
    if key in xml:
        return xml[key]
    return None


